functionList.push(['channels.manage','Manage social connections','Add channels and manage connection health.','Administration'],['assets.manage','Manage asset groups','Create groups and link or unlink assigned channels.','Administration'],['assets.delete','Delete asset groups','Delete a group without deleting its channels.','Administration']);
menuIconPaths.channels='M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2';
navSections[0][1].push(['channels','Social channels','',null]);
const pageAllowedBeforeChannels=pageAllowed;pageAllowed=function(page){if(page==='channels')return isAdmin()||can('channels.manage');if(page==='assets')return isAdmin()||can('assets.manage')||can('assets.delete');return pageAllowedBeforeChannels(page)};
function connectionState(channel){const c=channel.connection||{status:'Unknown',expiresAt:null};if(c.expiresAt&&new Date(c.expiresAt).getTime()<=Date.now())return 'Expired';if(c.expiresAt&&new Date(c.expiresAt).getTime()-Date.now()<7*86400000)return 'Expires soon';return c.status}
assetsData.channels.forEach((c,i)=>{if(!c.connection)c.connection={status:i%8===0?'Expired':'Healthy',expiresAt:new Date(Date.now()+(i%8===0?-1:i%6===0?3:45)*86400000).toISOString(),lastSync:nowISO()}});
persistAssets();
function editableChannels(){return assetsData.channels.filter(c=>accountAllowed(c.id))}
function editableAssetGroup(id){return isAdmin()||assetsData.channels.filter(c=>c.assetGroup===id).every(c=>accountAllowed(c.id))}
function unlinkGroupChannels(data,id){data.channels.forEach(c=>{if(c.assetGroup===id)c.assetGroup=null});data.groups=data.groups.filter(g=>g.id!==id);if(data.selected===id)data.selected=data.groups[0]?.id||null}
function canDeleteAssetGroup(user,admin){return Boolean(admin||user?.functions?.includes('assets.delete'))}
let channelSearch='',channelNetwork='All';
function showChannels(){document.querySelector('.crumb strong').textContent='Social channels';document.querySelector('#main').innerHTML=heading('Social channels','Independent connections. Link them to an Asset Group after creation.',can('channels.manage')?'<button class="btn primary" id="create-independent-channel">＋ Add social channel</button>':'')+`<div class="connection-boundary"><strong>Channels live independently of groups</strong><p>Each channel has its own connection health and token expiry. Group deletion never disconnects or deletes the channel. All connection states below are simulated.</p></div><div class="ops-filters"><label>Network<select id="channel-network">${['All',...networkOptions.map(n=>n.name)].map(n=>`<option ${n===channelNetwork?'selected':''}>${n}</option>`)}</select></label><label>Search<input id="channel-search" placeholder="Search channel name…" value="${safe(channelSearch)}"></label></div><div id="independent-channel-rows"></div>`;document.querySelector('#create-independent-channel')?.addEventListener('click',chooseIndependentNetwork);document.querySelector('#channel-network').onchange=e=>{channelNetwork=e.target.value;channelRows()};document.querySelector('#channel-search').oninput=e=>{channelSearch=e.target.value;channelRows()};channelRows()}
function channelRows(){const channels=editableChannels().filter(c=>(channelNetwork==='All'||c.network===channelNetwork)&&c.name.toLowerCase().includes(channelSearch.toLowerCase()));document.querySelector('#independent-channel-rows').innerHTML=`<section class="user-panel table-wrap"><table class="table user-table"><thead><tr><th>Channel</th><th>Asset group</th><th>Connection · demo</th><th>Token expiry · demo</th><th></th></tr></thead><tbody>${channels.map(c=>`<tr><td><div class="person">${channelAvatar(c)}<div><strong>${safe(c.name)}</strong><small>${c.network}</small></div></div></td><td>${safe(assetsData.groups.find(g=>g.id===c.assetGroup)?.name||'Unlinked')}</td><td><span class="badge ${connectionState(c)==='Expired'?'fail':connectionState(c)==='Expires soon'?'warn':'ok'}">${connectionState(c)}</span></td><td>${c.connection?.expiresAt?timeLabel(c.connection.expiresAt):'Not provided'}</td><td><button class="btn" data-manage-connection="${c.id}">Manage connection</button></td></tr>`).join('')||'<tr><td colspan="5">No accessible channels. New connections remain unassigned until an administrator grants channel access.</td></tr>'}</tbody></table></section>`;document.querySelectorAll('[data-manage-connection]').forEach(b=>b.onclick=()=>manageConnection(b.dataset.manageConnection))}
function chooseIndependentNetwork(){if(!can('channels.manage'))return;assetModal('Add social channel',`<p class="form-description">Create an independent demo connection first. Assign it to an Asset Group separately.</p><div class="connect-grid">${networkOptions.map(n=>`<button data-independent-network="${n.name}"><span style="background:${n.color}">${n.symbol}</span>${n.name}</button>`).join('')}</div><p class="ops-muted">No real OAuth, credentials or API calls. Token expiry values are simulated.</p>`);document.querySelectorAll('[data-independent-network]').forEach(b=>b.onclick=()=>createIndependentChannel(b.dataset.independentNetwork))}
function createIndependentChannel(network){if(!can('channels.manage'))return;assetModal('Add '+network,`<form id="independent-channel-form"><p class="form-description">The channel will be created with no Asset Group and no automatic user access.</p><div class="field"><label for="independent-name">Account display name</label><input id="independent-name" required maxlength="100" placeholder="Harbourview Community News"></div><div class="field"><label for="independent-expiry">Simulated token expiry</label><input id="independent-expiry" type="date" value="${new Date(Date.now()+45*86400000).toISOString().slice(0,10)}" required></div><p id="independent-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Create unlinked demo channel</button></div></form>`);document.querySelector('#independent-channel-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#independent-name').value.trim();if(!name)return;if(assetsData.channels.some(c=>c.network===network&&c.name.toLowerCase()===name.toLowerCase())){document.querySelector('#independent-error').textContent='A channel with this name and network already exists.';return}const expires=document.querySelector('#independent-expiry').value;assetsData.channels.push({id:crypto.randomUUID(),name,network,assetGroup:null,art:0,connection:{status:'Healthy',expiresAt:new Date(expires+'T23:59:59Z').toISOString(),lastSync:nowISO()}});persistAssets();logOps('Independent demo channel created',name+'; unlinked, no user access granted.');close();renderWorkspace('channels');toast('Channel created independently. Link it to a group when ready.')}}
function manageConnection(id){const c=assetsData.channels.find(c=>c.id===id);if(!c||!accountAllowed(id)||!can('channels.manage')){toast('Connection-management permission and channel access are required.');return}assetModal('Manage connection',`<div class="channel-detail-head">${channelAvatar(c,'large')}<div><strong>${safe(c.name)}</strong><p>${c.network} · ${connectionState(c)} · simulated</p></div></div><div class="field" style="margin-top:25px"><label for="connection-expiry">Simulated token expiry date</label><input type="date" id="connection-expiry" value="${c.connection.expiresAt.slice(0,10)}"></div><p class="ops-muted">Asset group: ${safe(assetsData.groups.find(g=>g.id===c.assetGroup)?.name||'Unlinked')}. This metadata is independent of the channel token.</p><div class="actions"><button class="btn" id="save-token-expiry">Save demo expiry</button><button class="btn primary" id="reauthorize-channel">Mock reauthorize · 60 days</button></div>`);document.querySelector('#save-token-expiry').onclick=()=>{const value=document.querySelector('#connection-expiry').value;if(!value){toast('Choose a date.');return}c.connection.expiresAt=new Date(value+'T23:59:59Z').toISOString();persistAssets();logOps('Demo token expiry updated',c.name);close();renderWorkspace('channels')};document.querySelector('#reauthorize-channel').onclick=()=>{c.connection={status:'Healthy',expiresAt:new Date(Date.now()+60*86400000).toISOString(),lastSync:nowISO()};persistAssets();logOps('Mock channel reauthorization',c.name+'; no provider called.');close();renderWorkspace('channels');toast('Demo expiry extended. No real token was obtained.')}}
function linkExistingChannels(){if(!can('assets.manage')||!editableAssetGroup(assetsData.selected)){toast('Asset-group management permission and channel access are required.');return}const group=assetsData.groups.find(g=>g.id===assetsData.selected);const available=editableChannels().filter(c=>!c.assetGroup||c.assetGroup===group.id);assetModal('Link existing social channels',`<form id="link-channel-form"><p class="form-description">Choose connections for ${safe(group.name)}. Unchecking a channel unlinks it; its connection, token metadata and user assignments remain unchanged.</p><div class="resource-list">${available.map(c=>`<label class="resource-option"><input type="checkbox" name="group-channel-link" value="${c.id}" ${c.assetGroup===group.id?'checked':''}>${channelAvatar(c)}<span><strong>${safe(c.name)}</strong><small>${c.network} · ${connectionState(c)}</small></span></label>`).join('')||'<p>No unlinked accessible channels. Create a channel in Social channels first.</p>'}</div><p class="ops-muted">Channels in another group must be unlinked there before linking here.</p><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Save links</button></div></form>`);document.querySelector('#link-channel-form').onsubmit=e=>{e.preventDefault();const chosen=[...document.querySelectorAll('[name="group-channel-link"]:checked')].map(c=>c.value);available.forEach(c=>c.assetGroup=chosen.includes(c.id)?group.id:null);persistAssets();logOps('Asset-group channel links updated',group.name);close();renderWorkspace('assets')}}
function deleteAssetGroupDialog(){const group=assetsData.groups.find(g=>g.id===assetsData.selected);if(!group||!canDeleteAssetGroup(currentUser(),isAdmin())||!editableAssetGroup(group.id)){toast('Delete asset groups permission and access to linked channels are required.');return}const count=assetsData.channels.filter(c=>c.assetGroup===group.id).length;assetModal('Delete asset group',`<form id="delete-asset-form"><p class="form-description">Delete <strong>${safe(group.name)}</strong>? ${count} social channels will become unlinked. Their connections, token expiry, content, cases and independent user account permissions will remain intact. Group-scoped roles will end with the group.</p><p class="ops-muted">This demo archives the group’s saved brand guidance for recovery.</p><div class="field"><label for="delete-group-confirm">Type DELETE to confirm</label><input id="delete-group-confirm" required pattern="DELETE" autocomplete="off"></div><button class="btn danger" type="submit">Delete group only</button></form>`);document.querySelector('#delete-asset-form').onsubmit=e=>{e.preventDefault();if(document.querySelector('#delete-group-confirm').value!=='DELETE')return;if(!canDeleteAssetGroup(currentUser(),isAdmin())){toast('Permission denied.');return}assetsData.archivedGroups=assetsData.archivedGroups||[];assetsData.archivedGroups.push({...group,archivedAt:nowISO()});unlinkGroupChannels(assetsData,group.id);persistAssets();logOps('Asset group deleted; channels retained',group.name+'; '+count+' channels unlinked.');close();renderWorkspace('assets');toast('Group deleted. All social channels and connection metadata retained.')}}
const assetsBeforeIndependentChannels=showAssetGroups;showAssetGroups=function(){if(!assetsData.groups.length){document.querySelector('#main').innerHTML=heading('Asset groups','No groups yet. Your independent social channels are still available.',can('assets.manage')?'<button class="btn primary" id="empty-new-group">Create asset group</button>':'')+'<section class="card"><p>Deleting the last group does not delete any channel.</p></section>';document.querySelector('#empty-new-group')?.addEventListener('click',newAssetGroup);return}assetsBeforeIndependentChannels();const add=document.querySelector('#connect-social');if(add){const linkButton=add.cloneNode(true);add.replaceWith(linkButton);linkButton.textContent='＋ Link existing channels';linkButton.disabled=!can('assets.manage')||!editableAssetGroup(assetsData.selected);linkButton.onclick=linkExistingChannels}document.querySelector('#new-asset-group')?.toggleAttribute('disabled',!can('assets.manage'));const header=document.querySelector('.asset-header');if(header&&canDeleteAssetGroup(currentUser(),isAdmin())){const button=document.createElement('button');button.className='btn danger';button.textContent='Delete group';button.disabled=!editableAssetGroup(assetsData.selected);button.onclick=deleteAssetGroupDialog;header.append(button)}};
const oldNewAssetGroup=newAssetGroup;newAssetGroup=function(){if(!can('assets.manage')){toast('Manage asset groups permission required.');return}oldNewAssetGroup()};
connectSocial=chooseIndependentNetwork;
const workspaceBeforeIndependentChannels=renderWorkspace;renderWorkspace=function(page=currentPage){if(page==='channels'){workspaceBeforeIndependentChannels('channels');if(pageAllowed('channels'))showChannels()}else workspaceBeforeIndependentChannels(page)};
const assetViewBeforeScope=showAssetGroups;showAssetGroups=function(){if(isAdmin())return assetViewBeforeScope();const allGroups=assetsData.groups,allChannels=assetsData.channels;const allowed=allGroups.filter(g=>allChannels.filter(c=>c.assetGroup===g.id).every(c=>accountAllowed(c.id)));if(!allowed.length){document.querySelector('#main').innerHTML=heading('Asset groups','No Asset Group is fully within your assigned channel scope.')+emptyAccess();return}if(!allowed.some(g=>g.id===assetsData.selected))assetsData.selected=allowed[0].id;try{assetsData.groups=allowed;assetsData.channels=allChannels.filter(c=>accountAllowed(c.id));return assetViewBeforeScope()}finally{assetsData.groups=allGroups;assetsData.channels=allChannels}};
renderWorkspace('channels');
